#include <stdio.h>

static const uint32_t CC[4] = {0x61707865, 0x3320646e, 0x79622d32, 0x6b206574};

#define ROTL32(x,n) (((x)<<(n)) | ((x)>>(32-(n))))
#define QR(a,b,c,d) do { \
    a += b; d ^= a; d = ROTL32(d,16); \
    c += d; b ^= c; b = ROTL32(b,12); \
    a += b; d ^= a; d = ROTL32(d,8); \
    c += d; b ^= c; b = ROTL32(b,7); \
} while(0)

static uint32_t le32(const uint8_t *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1]<<8) | ((uint32_t)p[2]<<16) | ((uint32_t)p[3]<<24);
}

static void chacha20_block(uint32_t out[16], const uint32_t key[8], const uint32_t nonce[3], uint32_t counter) {
    uint32_t x[16];
    x[0]=CC[0]; x[1]=CC[1]; x[2]=CC[2]; x[3]=CC[3];
    for (int i=0;i<8;i++) x[4+i]=key[i];
    x[12]=counter;
    x[13]=nonce[0]; x[14]=nonce[1]; x[15]=nonce[2];
    uint32_t in[16];
    memcpy(in, x, 64);
    for (int r=0;r<10;r++) {
        QR(x[0],x[4],x[8],x[12]);
        QR(x[1],x[5],x[9],x[13]);
        QR(x[2],x[6],x[10],x[14]);
        QR(x[3],x[7],x[11],x[15]);
        QR(x[0],x[5],x[10],x[15]);
        QR(x[1],x[6],x[11],x[12]);
        QR(x[2],x[7],x[8],x[13]);
        QR(x[3],x[4],x[9],x[14]);
    }
    for (int i=0;i<16;i++) out[i]=x[i]+in[i];
}

static void chacha20_xor(uint8_t *out, const uint8_t *in, size_t len, const uint32_t key[8], const uint32_t nonce[3], uint32_t counter) {
    uint32_t block[16];
    uint8_t ks[64];
    size_t pos = 0;
    while (pos < len) {
        chacha20_block(block, key, nonce, counter++);
        for (int i=0;i<16;i++) {
            ks[i*4] = block[i] & 0xff;
            ks[i*4+1] = (block[i]>>8) & 0xff;
            ks[i*4+2] = (block[i]>>16) & 0xff;
            ks[i*4+3] = (block[i]>>24) & 0xff;
        }
        size_t n = len - pos;
        if (n > 64) n = 64;
        for (size_t i=0;i<n;i++) out[pos+i] = in[pos+i] ^ ks[i];
        pos += n;
    }
}

// ---- Poly1305 ----
typedef struct {
    uint64_t h[5];
    uint64_t r[5];
    uint64_t s[4];
} poly1305_ctx;

static void poly1305_init(poly1305_ctx *c, const uint8_t key[32]) {
    uint64_t t0 = le32(key+0);
    uint64_t t1 = le32(key+4);
    uint64_t t2 = le32(key+8);
    uint64_t t3 = le32(key+12);
    t0 &= 0x0fffffff;
    t1 &= 0x0ffffffc;
    t2 &= 0x0ffffffc;
    t3 &= 0x0ffffffc;
    c->r[0] = t0 & 0x3ffffff;
    c->r[1] = ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
    c->r[2] = ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
    c->r[3] = ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
    c->r[4] = (t3 >> 8) & 0x3ffffff;
    c->s[0] = le32(key+16);
    c->s[1] = le32(key+20);
    c->s[2] = le32(key+24);
    c->s[3] = le32(key+28);
    for (int i=0;i<5;i++) c->h[i]=0;
}

static void poly1305_block(poly1305_ctx *c, const uint8_t *m) {
    uint64_t h0=c->h[0], h1=c->h[1], h2=c->h[2], h3=c->h[3], h4=c->h[4];
    uint64_t r0=c->r[0], r1=c->r[1], r2=c->r[2], r3=c->r[3], r4=c->r[4];

    h0 += le32(m+0) & 0x3ffffff;
    h1 += (le32(m+3) >> 2) & 0x3ffffff;
    h2 += (le32(m+6) >> 4) & 0x3ffffff;
    h3 += (le32(m+9) >> 6) & 0x3ffffff;
    h4 += (le32(m+12) >> 8) | 0x1000000;

    __uint128_t d0 = (__uint128_t)h0*r0 + (__uint128_t)h1*5*r4 + (__uint128_t)h2*5*r3 + (__uint128_t)h3*5*r2 + (__uint128_t)h4*5*r1;
    __uint128_t d1 = (__uint128_t)h0*r1 + (__uint128_t)h1*r0 + (__uint128_t)h2*5*r4 + (__uint128_t)h3*5*r3 + (__uint128_t)h4*5*r2;
    __uint128_t d2 = (__uint128_t)h0*r2 + (__uint128_t)h1*r1 + (__uint128_t)h2*r0 + (__uint128_t)h3*5*r4 + (__uint128_t)h4*5*r3;
    __uint128_t d3 = (__uint128_t)h0*r3 + (__uint128_t)h1*r2 + (__uint128_t)h2*r1 + (__uint128_t)h3*r0 + (__uint128_t)h4*5*r4;
    __uint128_t d4 = (__uint128_t)h0*r4 + (__uint128_t)h1*r3 + (__uint128_t)h2*r2 + (__uint128_t)h3*r1 + (__uint128_t)h4*r0;

    uint64_t cc;
