    d1 += cc; cc = (uint64_t)(d1 >> 26); h1 = (uint64_t)d1 & 0x3ffffff;
    d2 += cc; cc = (uint64_t)(d2 >> 26); h2 = (uint64_t)d2 & 0x3ffffff;
    d3 += cc; cc = (uint64_t)(d3 >> 26); h3 = (uint64_t)d3 & 0x3ffffff;
    d4 += cc; cc = (uint64_t)(d4 >> 26); h4 = (uint64_t)d4 & 0x3ffffff;
    h0 += cc * 5; cc = h0 >> 26; h0 &= 0x3ffffff;
    h1 += cc;

    c->h[0]=h0; c->h[1]=h1; c->h[2]=h2; c->h[3]=h3; c->h[4]=h4;
}

static void poly1305_finish(poly1305_ctx *c, uint8_t tag[16]) {
    uint64_t h0=c->h[0], h1=c->h[1], h2=c->h[2], h3=c->h[3], h4=c->h[4];
    uint64_t cc;
    cc = h1 >> 26; h1 &= 0x3ffffff;
    h2 += cc; cc = h2 >> 26; h2 &= 0x3ffffff;
    h3 += cc; cc = h3 >> 26; h3 &= 0x3ffffff;
    h4 += cc; cc = h4 >> 26; h4 &= 0x3ffffff;
    h0 += cc * 5; cc = h0 >> 26; h0 &= 0x3ffffff;
    h1 += cc;

    uint64_t g0 = h0 + 5;
    uint64_t g1 = h1 + (g0 >> 26); g0 &= 0x3ffffff;
    uint64_t g2 = h2 + (g1 >> 26); g1 &= 0x3ffffff;
    uint64_t g3 = h3 + (g2 >> 26); g2 &= 0x3ffffff;
    uint64_t g4 = h4 + (g3 >> 26) - (1ull << 26); g3 &= 0x3ffffff;
    uint64_t mask = (g4 >> 63) - 1;
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
